	/**
	 * It must be inserted after (Edit1 Edit2 HKIAdjustment) and before Edit3  
	 * For merging the discrepencies between two adjustments by Fredrick and Jacob
	 * @param net
	 * @param lane
	 * @param signalsData
	 */
	private static void JacobHKIConflictFix(Network net, Lanes lane, SignalsData signalsData) {
		//#1	the peak, remove node 17533 and links 17553_102222 102222_17553
		CreateNetworkUtils.removeLinkLane(net, lane, signalsData, Id.createLinkId("17553_102222"), Id.createLinkId("102222_17553"));
		net.removeNode(Id.createNodeId("17533"));
		
		//#2	Barbington Path -> Robinson Road, remove link 101827_103056
		CreateNetworkUtils.removeLinkLane(net, lane, signalsData, Id.createLinkId("101827_103056"));
		JacobTest.TESTmodifyNextLinksInLane(lane, Id.createLinkId("101828_101827"), 0, Id.createLinkId("101827_17250"));
		
		//#3	Old Peak Road May Road Tregunter Path
		//remove links 104202_102237 102237_104201 104201_101835 104203_18268 18268_104203 remove node 18268
		CreateNetworkUtils.removeLinkLane(net, lane, signalsData, Id.createLinkId("104202_102237"), Id.createLinkId("102237_104201"), Id.createLinkId("104201_101835"), Id.createLinkId("104203_18268"), Id.createLinkId("18268_104203"));
		net.removeNode(Id.createNodeId("18268"));
	}
	
