		JacobTest.TESTaddLaneIntoSignalAndGroup(signalsData, "401467_401454_1", 1);
		JacobTest.TESTaddLaneIntoSignalAndGroup(signalsData, "401467_401454_2", 1);
		
		//#3	509161, add 509160_509161 into siggroup 0
		JacobTest.TESTaddLaneIntoSignalAndGroup(signalsData, "509160_509161_0", 0);
		
		//#6	503770, fix 507120_503770, 0&1 in to 0, 2 into 1
		JacobTest.TESTaddLaneIntoSignalAndGroup(signalsData, "507120_503770_0", 0);
		JacobTest.TESTaddLaneIntoSignalAndGroup(signalsData, "507120_503770_1", 0);
		JacobTest.TESTaddLaneIntoSignalAndGroup(signalsData, "507120_503770_2", 1);
		
		//#11	401021, create new group for 408380_401021_0 and 1
		JacobTest.TESTaddLaneIntoSignalAndGroup(signalsData, "408380_401021_0", 1);
