	/**
	 * !!!Apply before NTW Adjustments Edit 1!!!<p>
	 * Includes Envisioned TunMun-ChekLapKok-Link (Tun Mun side)<br>
	 * which is wrong, so might as well remove the whole thing<br>
	 * and build the real thing later
	 * @param net
	 * @param lanes
	 * @param sig
	 * @author JLo
	 */
	private static void JacobRemoveTunMunBypassEnvisioned(Network net, Lanes lanes, SignalsData sig) {
		//!!!Apply before NTW Adjustments Edit 1!!!
		
		//the remove part
		String[] linksToRemove = {	"870038_870041"};
		String[] nodesToRemove = {	"870011", "870012", "870016", "870018", "870024",
									"870020", "870021", "870029", "870040", "870038"};
		String[] nodeAndLinksToRemove = {	"870006", "870007", "870009", "870008", "870010",
											"870015", "870017", "870019",
											"870025", "870023", "870022", 
											"870028", "870030", "870032", "870031", "870033", "870034", "870039"};
		for(String Tlink:linksToRemove)
			CreateNetworkUtils.removeLinkLane(net, lanes, sig, Id.createLinkId(Tlink));
		for(String Tnode:nodesToRemove)
			net.removeNode(Id.createNodeId(Tnode));
		for(String Tnode:nodeAndLinksToRemove) {
			Node TNode = net.getNodes().get(Id.createNodeId(Tnode));
			for(Id<Link> TLinkId:TNode.getInLinks().keySet())
				CreateNetworkUtils.removeLinkLane(net, lanes, sig, TLinkId);
			for(Id<Link> TLinkId:TNode.getOutLinks().keySet())
				CreateNetworkUtils.removeLinkLane(net, lanes, sig, TLinkId);
			net.removeNode(TNode.getId());
		}
		
		//fixing the mess left behind
		//Tsing Tin Rd
		JacobTest.TESTcombineLinks(net, lanes, sig, true, "870027_875303", "875305_870027");
		JacobTest.TESTcombineLinks(net, lanes, sig, true, "870026_875305", "875303_870026");
		//Kong Sham Western Highway
		Link link0 = JacobTest.TESTrenumlaneLink(net, lanes, Id.createLinkId("874331_870005"), 3);
		CreateNetworkUtils.addNextLinksToLane(lanes, link0, 0, 3, Id.createLinkId("870005_870013"));
		
	}
	
