	private static void JacobFullHKSignalAdjustment(Network net, Lanes lanes, SignalsData sig) {		
		//Siu Lek Yuen 653179 & 653160
		JacobTest.removeSignalFromGroup(sig, "653179", 0, 7);
		JacobTest.removeSignalFromGroup(sig, "653160", 4, 7);
		
		//TODO: Temp fixes for new years sim -> added 10sec to each of these sig group WITHOUT adjusting the others
		JacobTest.increaseSignalDuration(sig, "652011", 3, 10);	//org 12 sec, fm 652081
		JacobTest.increaseSignalDuration(sig, "401287", 0, 10);	//org 16 sec, fm 402027
		JacobTest.increaseSignalDuration(sig, "653160", 0, 10);	//org 14 sec, fm 653168
		
		//#36_2	401864
		JacobTest.TESTaddLaneIntoSignalAndGroup(sig, "404027_401864_0", 0);
		JacobTest.TESTaddLaneIntoSignalAndGroup(sig, "404027_401864_1", 0);
		JacobTest.TESTaddLaneIntoSignalAndGroup(sig, "404027_401864_2", 0);
		JacobTest.TESTaddLaneIntoSignalAndGroup(sig, "404027_401864_3", 0);
		JacobTest.removeSignalFromGroup(sig, "401864", 0, 1);
		JacobTest.TESTaddLaneIntoSignalAndGroup(sig, "401862_401864_0", 1);
		
		//Tsz Wan Shan
		SignalPlanData thePlan = sig.getSignalControlData().getSignalSystemControllerDataBySystemId().get(Id.create("507100", SignalSystem.class)).getSignalPlanData().get(Id.create("1", SignalPlan.class));
		thePlan.getSignalGroupSettingsDataByGroupId().get(Id.create("0", SignalGroup.class)).setOnset(85);
		thePlan.getSignalGroupSettingsDataByGroupId().get(Id.create("0", SignalGroup.class)).setDropping(115);
		thePlan.getSignalGroupSettingsDataByGroupId().get(Id.create("1", SignalGroup.class)).setOnset(0);
		thePlan.getSignalGroupSettingsDataByGroupId().get(Id.create("1", SignalGroup.class)).setDropping(50);
		thePlan.getSignalGroupSettingsDataByGroupId().get(Id.create("2", SignalGroup.class)).setOnset(55);
		thePlan.getSignalGroupSettingsDataByGroupId().get(Id.create("2", SignalGroup.class)).setDropping(80);
		
	}
	
	private static void JacobHKISignalAdjustment(Network net, Lanes lanes, SignalsData sig) {
		//TODO: Temp fixes for new years sim -> added 10sec to each of these sig group WITHOUT adjusting the others
		JacobTest.increaseSignalDuration(sig, "303070", 1, 10);
	}
	
	public static void allAdjustment(Network net, Lanes lanes, SignalsData signalsData) {
		nTWAdjustment1(net, lanes, signalsData);
		ntwAdjustment2(net, lanes, signalsData);
		KowloonAdjustment1(net, lanes, signalsData);
		HKIAdjustment1(net, lanes, signalsData);
		HKIAdjustment2(net, lanes, signalsData);
		HKIAdjustment3(net, lanes, signalsData);
		HKIAdjustment4(net, lanes, signalsData);
		JacobAdjustmentsAll(net, lanes, signalsData);
	}
	
	public static void hkiAdjustment(Network net, Lanes lanes, SignalsData signalsData) {
		HKIAdjustment1(net, lanes, signalsData);
		HKIAdjustment2(net, lanes, signalsData);
		HKIAdjustment3(net, lanes, signalsData);
		HKIAdjustment4(net, lanes, signalsData);
		JacobHKIAdjustmentsEdit1(net, lanes, signalsData);
		JacobHKIAdjustmentsEdit2(net, lanes, signalsData);
		JacobHKIConflictFix(net, lanes, signalsData);			//MUST insert after (Edit1 Edit2 HKIAdjustment) and before Edit3  
		JacobHKIAdjustmentsEdit3(net, lanes, signalsData);
		jacobHKIAdjustmentsEdit4(net, lanes, signalsData);
		JacobHKIAdjustmentsEdit5(net, lanes, signalsData);
		JacobHKIAdjustmentsEdit6(net, lanes, signalsData, true);
		JacobHKIAdjustmentEdit7(net, lanes, signalsData);
		JacobHKISignalAdjustment(net, lanes, signalsData);
		
	}
	
	
